```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT ?e ?lei ?b ?r ?w ?ob WHERE {
?a lad:ratingType lad:type-LTIDR; lad:ratedThing ?e; lad:date ?d; lad:ccyBasis ?b; lad:rating ?r. ?e lad:lei ?lei
OPTIONAL{?a lad:watch ?w} OPTIONAL{?a lad:outlook ?ob}
FILTER(STR(?d)<="2026-10-01")
FILTER NOT EXISTS {?a2 lad:ratingType lad:type-LTIDR; lad:ratedThing ?e; lad:ccyBasis ?b; lad:date ?d2 FILTER(STR(?d2)<="2026-10-01" && STR(?d2)>STR(?d))}
