```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT (COUNT(DISTINCT ?lei) AS ?all) (COUNT(DISTINCT ?leiGB) AS ?gb) WHERE {
?a lad:ratingType lad:type-LTIDR; lad:ratedThing ?e; lad:date ?d; lad:ccyBasis ?b; lad:rating ?r. ?e lad:lei ?lei; lad:country ?c
FILTER(STR(?d)<="2026-10-01" && ?r != "WD")
FILTER NOT EXISTS {?a2 lad:ratingType lad:type-LTIDR; lad:ratedThing ?e; lad:ccyBasis ?b; lad:date ?d2 FILTER(STR(?d2)<="2026-10-01" && STR(?d2)>STR(?d))}
BIND(IF(?c="GB",?lei,?unb) AS ?leiGB)
}
```

```sparql
PREFIX lad: <https://example.org/ladder/>
SELECT (COUNT(DISTINCT ?i) AS ?rated) (COUNT(DISTINCT ?ig) AS ?investgrade) WHERE {
?a lad:ratingType lad:type-INST; lad:ratedThing ?i; lad:date ?d; lad:rating ?r; lad:action ?act
FILTER(STR(?d)<="2026-10-01" && ?r != "WD" && ?act != lad:action-EX)
FILTER NOT EXISTS {?a2 lad:ratingType lad:type-INST; lad:ratedThing ?i; lad:date ?d2 FILTER(STR(?d2)<="2026-10-01" && STR(?d2)>STR(?d))}
BIND(IF(?r IN ("AAA","AA+","AA","AA-","A+","A","A-","BBB+","BBB","BBB-"),?i,?unb) AS ?ig)
}
```

